// ---------------------------------------------------------------------------
//  DSA paged-MQA gated top-k logits (gfx942), issue #51.
//
//  The INDEXER (sglang _get_topk_paged) scores each query against its paged
//  KV tiles and the top-k selects over the results. GLM-5.3-Flash runs this
//  with num_heads = 32, head_dim = 128, block = 64 (hardcoded in deep_gemm).
//  The original gfx942 paths both fail: tilelang_fp8_paged_mqa_logits JIT-
//  compiles but the launched kernel NEVER returns (silent hang, ~30+ min,
//  all 4 ranks) for num_heads in {32,64}; deep_gemm.fp8_paged_mqa_logits is
//  CUDA-only (NameError on HIP). This kernel is the plain gfx942 replacement.
//
//  FP8 e4m3fnuz Q/K are dequantized to fp32 on load (mirrors dsa_sparse_fwd's
//  bf16->fp32). One wavefront per (batch, split_kv) block stages Q (H*D
//  fp32), the per-head gate (H fp32), and -- per page -- one K tile (B*D
//  fp8->fp32) plus the B per-token scales (fp32, packed in the trailing B*4
//  bytes of each KV block). Total shared = (H*D + H + B*D + B) * 4 = 49,536 B
//  at the GLM-5.3 config (H=32, D=128, B=64) -- UNDER the 64 KB non-optin LDS
//  cap, so NO hipFuncSetAttribute opt-in (unlike the MHC 256 KB bug).
//
//  Each of the B=64 lanes owns ONE KV token within the current page and
//  computes its gated logit
//
//    out[b, i*B + lane] = k_scale[page[b,i], lane]
//                         * Sum_h ( max(0, Sum_d Q[b,h,d]*K[page[b,i],lane,d] )
//                                   * gate[b,h] )
//
//  for t = i*B+lane < seq_len[b]; tokens >= seq_len[b] are left unwritten
//  (the caller ZEROES the output first; sglang's topk_from_pooled_history_logits
//  masks invalid positions via group_lengths/topk_offsets before the top-k).
//
//  This is the simple, correct baseline (one lane per key, sequential H-sum,
//  K staged once per page and reused across all H heads) -- the topk's
//  counterpart to dsa_sparse_fwd's "one query row per wavefront, one key at
//  a time". A tiled-key / MFMA-fp8 prefetch is a follow-on optimisation, not
//  required for correctness (the forward's docstring makes the same note).
//
//  Tensors (all device, row-major; kv_group == 1):
//    q_fp8       [bs, H, D]                 fp8 e4m3fnuz (raw uint8)
//    kvcache_u8  [num_blocks, B*(D+4)]      uint8 (B*D fp8 keys, then B fp32)
//    weight      [bs, H]                    fp32 (the gate, after .squeeze(2))
//    seq_lens    [bs]                       int32 (the POOLED valid KV count)
//    page_table  [bs, max_table_len]        int32 (page_table[b,i] indexes
//                                                  the num_blocks dim)
//    out         [bs, max_seq_len]          fp32 (max_seq_len = max_table_len*B;
//                                                  ZERO the output first)
// ---------------------------------------------------------------------------
__global__ void dsa_topk_logits_kernel(
    const uint8_t* __restrict__ q_fp8,
    const uint8_t* __restrict__ kvcache_u8,
    const float* __restrict__ weight,
    const int32_t* __restrict__ seq_lens,
    const int32_t* __restrict__ page_table,
    float* __restrict__ out,
    int H, int D, int B, int max_table_len, int max_seq_len, int split_kv) {
  const int b = blockIdx.x;
  const int pid_split = blockIdx.y;
  const int lane = threadIdx.x;                // 0..B-1 -> KV token j

  const int seq_len = seq_lens[b];
  const int np_total = (seq_len + B - 1) / B;  // pages with content
  const int stride = (np_total + split_kv - 1) / split_kv;
  const int i_start = pid_split * stride;
  const int rem = np_total - i_start;
  const int n_iters = (rem <= 0) ? 0 : (stride < rem ? stride : rem);
  if (n_iters <= 0) return;

  extern __shared__ float smem[];
  float* sQ = smem;                            // H * D
  float* sGate = sQ + (size_t)H * D;           // H
  float* sK = sGate + H;                       // B * D (reloaded per page)
  float* sKscale = sK + (size_t)B * D;         // B

  // --- cooperative load Q (H*D fp8 -> fp32) + gate (H fp32) once per block ---
  const uint8_t* qp = q_fp8 + (size_t)b * H * D;
  for (int idx = lane; idx < H * D; idx += B) sQ[idx] = fp8e4m3fnuz_to_f32(qp[idx]);
  const float* gp = weight + (size_t)b * H;
  for (int h = lane; h < H; h += B) sGate[h] = gp[h];
  __syncthreads();

  for (int it = 0; it < n_iters; ++it) {
    const int i = i_start + it;
    const int32_t page = page_table[(size_t)b * max_table_len + i];
    const uint8_t* kbase = kvcache_u8 + (size_t)page * (B * (D + 4));
    // keys: B*D fp8 e4m3fnuz (bytes [0 : B*D]); scales: B fp32 (bytes
    // [B*D : B*(D+4)], 4-aligned). Cooperative load into shared.
    for (int idx = lane; idx < B * D; idx += B) sK[idx] = fp8e4m3fnuz_to_f32(kbase[idx]);
    for (int j = lane; j < B; j += B) sKscale[j] = reinterpret_cast<const float*>(kbase + B * D)[j];
    __syncthreads();

    // --- this lane owns KV token j = lane within the page ---
    const float* kj = sK + (size_t)lane * D;
    float acc = 0.0f;
    for (int h = 0; h < H; ++h) {
      const float* qh = sQ + (size_t)h * D;
      float dot = 0.0f;
      for (int d = 0; d < D; ++d) dot += kj[d] * qh[d];
      acc += fmaxf(dot, 0.0f) * sGate[h];
    }
    const int t = i * B + lane;
    if (t < seq_len) out[(size_t)b * max_seq_len + t] = sKscale[lane] * acc;

    __syncthreads();                           // before reloading sK next iter
  }
}

void dsa_topk_logits(int batch_size, int num_heads, int head_dim, int block,
                     int max_table_len, int max_seq_len, int split_kv,
                     const void* q_fp8, const void* kvcache_u8,
                     const void* weight, const void* seq_lens,
                     const void* page_table, void* out) {
  if (batch_size <= 0 || max_table_len <= 0) return;  // nothing to write
  const int shmem = (num_heads * head_dim + num_heads +
                     block * head_dim + block) * sizeof(float);
  // One wavefront (B=64 lanes), one KV token per lane. Grid splits the
  // pages across split_kv blocks per batch (perf only; grouping-independent,
  // mirrors the forward's block_I/inner_iter). Stream 0 matches dsa_sparse_fwd;
  // the caller synchronises (see vkernels_dsa.tilelang_fp8_paged_mqa_logits).
  dim3 grid(batch_size, split_kv, 1);
  dim3 blockdim(block);
  dsa_topk_logits_kernel<<<grid, blockdim, shmem, 0>>>(
      reinterpret_cast<const uint8_t*>(q_fp8),
      reinterpret_cast<const uint8_t*>(kvcache_u8),
      reinterpret_cast<const float*>(weight),
      reinterpret_cast<const int32_t*>(seq_lens),
      reinterpret_cast<const int32_t*>(page_table),
      reinterpret_cast<float*>(out),
      num_heads, head_dim, block, max_table_len, max_seq_len, split_kv);
}

}  // namespace vkernels::kernels::hip

#endif  // VKERNELS_HAS_HIP

void dsa_config_for(int S_q, int H, int dim, int topk, int* bq, int* threads,
                    int* block_I, int* inner_iter) {
  (void)H;
  (void)dim;
  // Decode: a single query streams its `topk` selected keys; one wavefront
  // keeps the per-row online state in registers and saturates the CUs.
  // Prefill: BQ query rows per block shares the key reads across rows.
  if (S_q <= 8) {
    *bq = 1;
    *threads = 64;  // one wavefront
  } else {
    *bq = 4;
    *threads = 256;  // four wavefronts
  }
  *block_I = 64;
  // inner_iter so that block_I * inner_iter divides topk (power-of-two topk
  // is the common case; fall back to 1).
  int ii = 1;
  while (ii < 8 && topk % (*block_I * (ii * 2)) == 0) ii *= 2;
  *inner_iter = ii;
}

// ---------------------------------------------------------------------------
//  DSA paged-MQA gated top-k logits — CPU reference (oracle), issue #51.
//  See dsa.hpp for the layout and the gated-logit formula. Pure fp32, single
//  pass (no softmax — the topk IS the softmax-free scoring stage). The HIP
//  kernel (dsa.hip) is cross-checked against this by test_dsa_topk_correct;
//  it dequants fp8 e4m3fnuz on load, the oracle takes dequanted fp32 (caller
//  dequants via torch.float8_e4m3fnuz, mirroring dsa_sparse_fwd_cpu).
//
//  Tokens t >= seq_len[b] are LEFT UNWRITTEN — the caller ZEROES the output
//  first (strictly safer than the tilelang wrapper's `new_empty`, harmless
//  under sglang's `topk_from_pooled_history_logits` masking).
// ---------------------------------------------------------------------------
void dsa_topk_logits_cpu(int batch_size, int num_heads, int head_dim, int block,
                         int max_table_len, int num_blocks,
                         const float* q, const float* kv,
                         const float* k_scale, const float* gate,
                         const int32_t* seq_lens, const int32_t* page_table,
                         float* out) {
  VK_EXPECTS(batch_size >= 0 && num_heads > 0 && head_dim > 0 && block > 0,
             "batch_size >= 0 and num_heads/head_dim/block > 0 required");
  VK_EXPECTS(max_table_len >= 0 && num_blocks >= 0,
             "max_table_len >= 0 and num_blocks >= 0 required");
  (void)max_table_len;  // only the page_table stride is used (caller-set)
  if (batch_size == 0 || max_table_len == 0) return;  // nothing to write

  for (int b = 0; b < batch_size; ++b) {
    const int seq_len = seq_lens[b];
    const int np_total = (seq_len + block - 1) / block;  // pages with content
    const int32_t* pt_b = page_table + (size_t)b * max_table_len;
    const float* qb = q + (size_t)b * num_heads * head_dim;
    const float* gb = gate + (size_t)b * num_heads;
    float* ob = out + (size_t)b * (size_t)max_table_len * block;
    for (int i = 0; i < np_total; ++i) {
      const int32_t page = pt_b[i];
      const float* kbase = kv + (size_t)page * block * head_dim;
      const float* sbase = k_scale + (size_t)page * block;
      for (int j = 0; j < block; ++j) {
        const int t = i * block + j;
        if (t >= seq_len) break;  // rest of this page is past seq_len
        const float* kj = kbase + (size_t)j * head_dim;
        float acc = 0.0f;
        for (int h = 0; h < num_heads; ++h) {
          const float* qh = qb + (size_t)h * head_dim;
          float dot = 0.0f;
          for (int d = 0; d < head_dim; ++d) dot += qh[d] * kj[d];
          acc += std::fmax(dot, 0.0f) * gb[h];
        }
        ob[t] = sbase[j] * acc;
      }
    }
  }
}

