// meta/benchmarks/test_dsa_correct.hip
//
// End-to-end correctness test for the DeepseekSparseAttn sparse-MLA forward
// (issue #51) on gfx942, against the CPU reference in
// vkernels::kernels::dsa_sparse_fwd_cpu.
//
//   hip::dsa_sparse_fwd  vs  dsa_sparse_fwd_cpu (two-pass base-2 softmax)
//
// Shapes: BOTH families the issue calls out —
//   * GLM-5.3-Flash : dim=256, tail_dim=0  -> W=256, d_v=256  (the layout the
//     tilelang code path cannot compile; the kernel skips the rope-tail dot
//     via tail_tiles == 0).
//   * DeepSeek-V3   : dim=576, tail_dim=64 -> W=640, d_v=512.
//
// at serving S_q in {1 (decode), 64 (short), 8192 (prefill)}. The indexer
// selects `topk` keys per query from [0, S_kv) with ~10% masked to -1 (the
// kpool-tail path the kernel must zero).
//
// Method. The CPU oracle is fp32 end-to-end; the device kernel is bf16
// storage / fp32 accumulation (the established gfx942 convention, identical
// to gemm_bf16.hip). To isolate the kernel's correctness from bf16 input
// quantization, the fp32 source is rounded to bf16 FIRST (host RNE), then the
// CPU oracle runs on the recovered fp32 and the device on the bf16 inputs —
// exactly as test_gemm_bf16_correct.hip does. Only online-vs-two-pass
// ordering and the single RNE on store differ, so they agree to within ~1 bf16
// ULP. We report max_abs / max_rel and require max_rel < 2e-2 for the output
// and < 1e-3 for the fp32 LSE.

#include <hip/hip_runtime.h>

#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>

#include "vkernels/kernels/dsa.hpp"

#define CK(e, m)                                                       \
  do {                                                                 \
    hipError_t r = (e);                                                \
    if (r != hipSuccess) {                                             \
      std::fprintf(stderr, "%s: %s\n", m, hipGetErrorString(r));       \
      std::exit(1);                                                    \
    }                                                                  \
  } while (0)

namespace {

float rnd(int seed, int i) {  // deterministic pseudo-random in [-1, 1]
  unsigned x = (unsigned)(seed * 2654435761u + (unsigned)i * 40503u);
  x ^= x >> 13;
  x *= 0x5bd1e995u;
  x ^= x >> 15;
  return (float)((int)x % 200000) / 100000.0f;
}

// Host bf16 (uint16 IEEE bit patterns) <-> fp32, RNE — identical to the
// helpers in gemm_bf16.cpp and to f32bits_to_bf16 in moe_device.hip.
uint16_t f2bf(float v) {
  uint32_t b;
  std::memcpy(&b, &v, sizeof(float));
  uint32_t lsb = (b >> 16) & 1;
  b += 0x7FFFu + lsb;
  return (uint16_t)(b >> 16);
}
float bf2f(uint16_t h) {
  uint32_t u = (uint32_t)h << 16;
  float f;
  std::memcpy(&f, &u, sizeof(float));
  return f;
}

struct Stats { double max_abs, max_rel; };
struct LseStats { double max_abs, max_rel, worst_inf; };

void cmp_out(const std::vector<float>& got, const std::vector<float>& ref,
             Stats* s) {
  for (size_t i = 0; i < ref.size(); ++i) {
    double e = std::fabs((double)got[i] - ref[i]);
    if (e > s->max_abs) s->max_abs = e;
    double d = std::fmax(std::fabs((double)ref[i]), 1.0);
    if (e / d > s->max_rel) s->max_rel = e / d;
  }
}

void cmp_lse(const std::vector<float>& got, const std::vector<float>& ref,
             LseStats* s) {
  for (size_t i = 0; i < ref.size(); ++i) {
    const float g = got[i], r = ref[i];
    const bool gi = std::isfinite(g), ri = std::isfinite(r);
    if (gi != ri) {                       // -inf vs finite is a hard failure
      s->worst_inf = INFINITY;
      continue;
    }
    if (!gi && !ri) continue;             // both -inf (fully masked): exact
    double e = std::fabs((double)g - r);
    if (e > s->max_abs) s->max_abs = e;
    double d = std::fmax(std::fabs((double)r), 1.0);
    if (e / d > s->max_rel) s->max_rel = e / d;
  }
}

struct CaseStats { Stats out; LseStats lse; };

CaseStats run_case(int S_q, int S_kv, int H, int dim, int tail_dim, int topk,
                   int kv_group, int block_I, int inner_iter, float sm_scale,
                   const std::vector<float>& q,    // fp32 source (S_q*H*W)
                   const std::vector<float>& kv,   // fp32 source (S_kv*W)
                   const std::vector<int32_t>& idx,// [S_q*topk]
                   uint16_t* dq, uint16_t* dkv, int32_t* didx, uint16_t* dout,
                   float* dlse) {
  const int W = dim + tail_dim;
  const int d_v = dim - tail_dim;
  const size_t nq = (size_t)S_q * H * W;
  const size_t nkv = (size_t)S_kv * W;
  const size_t nout = (size_t)S_q * H * d_v;
  const size_t nlse = (size_t)S_q * H;

  // Round source -> bf16, then recover to fp32 (the value BOTH paths see).
  std::vector<uint16_t> qb(nq), kb(nkv);
  std::vector<float> qr(nq), kr(nkv);
  for (size_t i = 0; i < nq; ++i) { qb[i] = f2bf(q[i]); qr[i] = bf2f(qb[i]); }
  for (size_t i = 0; i < nkv; ++i) { kb[i] = f2bf(kv[i]); kr[i] = bf2f(kb[i]); }

  // CPU oracle on the bf16-recovered inputs.
  std::vector<float> ref(nout, 0.0f), ref_lse(nlse, 0.0f);
  vkernels::kernels::dsa_sparse_fwd_cpu(
      S_q, S_kv, H, dim, tail_dim, topk, kv_group, block_I, inner_iter,
      sm_scale, /*return_lse=*/true, qr.data(), kr.data(), idx.data(),
      ref.data(), ref_lse.data());

  // Device.
  CK(hipMemcpy(dq, qb.data(), nq * 2, hipMemcpyHostToDevice), "cpyq");
  CK(hipMemcpy(dkv, kb.data(), nkv * 2, hipMemcpyHostToDevice), "cpykv");
  // indices are [1, S_q, kv_group==1, topk] -> S_q*topk int32 (the CPU
  // oracle and the kernel share the same single-head_kv selection).
  CK(hipMemcpy(didx, idx.data(), (size_t)S_q * topk * 4,
               hipMemcpyHostToDevice), "cpyidx");
  vkernels::kernels::hip::dsa_sparse_fwd(
      S_q, S_kv, H, dim, tail_dim, topk, kv_group, block_I, inner_iter,
      sm_scale, /*return_lse=*/true, dq, dkv, didx, dout, dlse);
  CK(hipDeviceSynchronize(), "sync");

  std::vector<uint16_t> hout(nout);
  std::vector<float> hlse(nlse);
  CK(hipMemcpy(hout.data(), dout, nout * 2, hipMemcpyDeviceToHost), "rdout");
  CK(hipMemcpy(hlse.data(), dlse, nlse * 4, hipMemcpyDeviceToHost), "rdlse");

  std::vector<float> got(nout);
  for (size_t i = 0; i < nout; ++i) got[i] = bf2f(hout[i]);

  CaseStats cs{};
  cmp_out(got, ref, &cs.out);
  cmp_lse(hlse, ref_lse, &cs.lse);
  return cs;
}

}  // namespace

int main() {
  hipDeviceProp_t p;
  CK(hipGetDeviceProperties(&p, 0), "props");
  std::printf("GPU: %s (arch=%s)\n", p.name, p.gcnArchName);

  const float LOG2E = 1.4426950408889634f;

  // Peak buffers across all cases (GLM-5.3 and DeepSeek-V3).
  const int Sqmax = 8192, Hmax = 64, Wmax = 640, Svmax = 4096;
  const int Dvmax = 512, Topkmax = 2048;
  uint16_t *dq, *dkv, *dout;
  int32_t* didx;
  float* dlse;
  CK(hipMalloc(&dq, (size_t)Sqmax * Hmax * Wmax * 2), "alloc q");
  CK(hipMalloc(&dkv, (size_t)Svmax * Wmax * 2), "alloc kv");
  CK(hipMalloc(&didx, (size_t)Sqmax * Topkmax * 4), "alloc idx");
  CK(hipMalloc(&dout, (size_t)Sqmax * Hmax * Dvmax * 2), "alloc out");
  CK(hipMalloc(&dlse, (size_t)Sqmax * Hmax * 4), "alloc lse");

  int fails = 0;
  const float OUT_THRESH = 2e-2f;
  const float LSE_THRESH = 1e-3f;

  struct Cfg { int S_q, S_kv, H, dim, tail_dim, topk; };
  const Cfg cfgs[] = {
      // GLM-5.3-Flash: tail_dim == 0 (the uncompilable tilelang case).
      {1, 128, 64, 256, 0, 128},     // decode, topk=128
      {1, 256, 64, 256, 0, 256},     // decode, topk=256
      {1, 2048, 64, 256, 0, 2048},   // decode, full topk=2048
      {64, 256, 1, 256, 0, 128},     // short
      {8192, 1024, 1, 256, 0, 128},  // prefill (H=1; CPU-tractable)
      // DeepSeek-V3: tail_dim > 0.
      {1, 256, 16, 576, 64, 256},    // decode, d_v=512
      {1, 512, 16, 576, 64, 256},    // decode, more keys
      {64, 256, 1, 576, 64, 256},    // short
      {8192, 1024, 1, 576, 64, 256}, // prefill (H=1)
      // Tiny hand-check shapes (sanity, both tail families).
      {1, 2, 1, 2, 0, 2},            // scores {1,1} -> {0.5,0.5}, lse=2
      {1, 2, 1, 2, 1, 2},            // tail>0: scores {2,3} -> 4/1.5
  };

  for (const auto& c : cfgs) {
    const int W = c.dim + c.tail_dim;
    const float sm_scale = (1.0f / std::sqrt((float)W)) * LOG2E;
    std::vector<float> q((size_t)c.S_q * c.H * W);
    std::vector<float> kv((size_t)c.S_kv * W);
    std::vector<int32_t> idx((size_t)c.S_q * c.topk);
    for (size_t i = 0; i < q.size(); ++i) q[i] = rnd(1, (int)i);
    for (size_t i = 0; i < kv.size(); ++i) kv[i] = rnd(2, (int)i);
    for (int i = 0; i < c.S_q; ++i)
      for (int k = 0; k < c.topk; ++k)
        idx[(size_t)i * c.topk + k] =
            (k % 10 == 9) ? -1 : (int32_t)(((unsigned)(i * 31 + k * 7)) %
                                           (unsigned)c.S_kv);

    auto st = run_case(c.S_q, c.S_kv, c.H, c.dim, c.tail_dim, c.topk, 1, 64,
                       1, sm_scale, q, kv, idx, dq, dkv, didx, dout, dlse);
    bool ok = st.out.max_rel < OUT_THRESH && st.lse.max_rel < LSE_THRESH &&
              st.lse.worst_inf < 1.0;
    std::printf("  S_q=%-4d S_kv=%-4d H=%-2d dim=%-3d tail=%-2d topk=%-4d  "
                "out[a=%.4f r=%.6f] lse[a=%.4f r=%.6f inf=%.1f]  %s\n",
                c.S_q, c.S_kv, c.H, c.dim, c.tail_dim, c.topk,
                st.out.max_abs, st.out.max_rel, st.lse.max_abs, st.lse.max_rel,
                st.lse.worst_inf, ok ? "PASS" : "FAIL");
    if (!ok) ++fails;
  }

  hipFree(dq); hipFree(dkv); hipFree(didx); hipFree(dout); hipFree(dlse);
  std::printf("\n%s (%d failure(s))\n", fails ? "FAIL" : "PASS", fails);
  return fails ? 1 : 0;
}

template <int BQ>
void launch(const void* q, const void* kv, const void* indices, void* out,
            void* lse, int S_q, int S_kv, int H, int dim, int tail_dim,
            int topk, int kv_group, float sm_scale, bool return_lse) {
  const int W = dim + tail_dim;
  const int shmem = BQ * W * sizeof(float);
  dim3 block(BQ * 64);
  dim3 grid((S_q + BQ - 1) / BQ, H, 1);
  dsa_sparse_fwd_kernel<BQ><<<grid, block, shmem, 0>>>(
      reinterpret_cast<const uint16_t*>(q),
      reinterpret_cast<const uint16_t*>(kv),
      reinterpret_cast<const int32_t*>(indices),
      reinterpret_cast<uint16_t*>(out), reinterpret_cast<float*>(lse),
      S_q, S_kv, H, dim, tail_dim, topk, kv_group, sm_scale, return_lse);
}
}  // namespace

void dsa_sparse_fwd_with_tile(int S_q, int S_kv, int H, int dim, int tail_dim,
                              int topk, int kv_group, float sm_scale,
                              bool return_lse,
                              const void* q, const void* kv,
                              const void* indices, void* out, void* lse,
                              int bq, int block_I, int inner_iter, int bn_kv) {
  (void)block_I;     // baseline streams one key at a time; reserved for a
  (void)inner_iter;  // future tiled-key prefetch (group-then-combine merge).
  (void)bn_kv;
  if (bq <= 1)
    launch<1>(q, kv, indices, out, lse, S_q, S_kv, H, dim, tail_dim, topk,
              kv_group, sm_scale, return_lse);
  else if (bq <= 2)
    launch<2>(q, kv, indices, out, lse, S_q, S_kv, H, dim, tail_dim, topk,
              kv_group, sm_scale, return_lse);
  else if (bq <= 4)
    launch<4>(q, kv, indices, out, lse, S_q, S_kv, H, dim, tail_dim, topk,
              kv_group, sm_scale, return_lse);
  else
    launch<8>(q, kv, indices, out, lse, S_q, S_kv, H, dim, tail_dim, topk,
              kv_group, sm_scale, return_lse);
}

void dsa_sparse_fwd(int S_q, int S_kv, int H, int dim, int tail_dim,
                    int topk, int kv_group, int block_I, int inner_iter,
                    float sm_scale, bool return_lse,
                    const void* q, const void* kv, const void* indices,
                    void* out, void* lse) {
  int bq = 0, th = 0, bi = 0, ii = 0;
  ::vkernels::kernels::dsa_config_for(S_q, H, dim, topk, &bq, &th, &bi, &ii);
  (void)th;
  (void)block_I;
  (void)inner_iter;
  dsa_sparse_fwd_with_tile(S_q, S_kv, H, dim, tail_dim, topk, kv_group,
                           sm_scale, return_lse, q, kv, indices, out, lse,
                           bq, bi, ii, 0);
}

// ---------------------------------------------------------------------------
//  DSA paged-MQA gated top-k logits (gfx942), issue #51. See dsa.hpp for the
//  gated-logit formula and the tensor layout; this kernel is the plain
//  gfx942 replacement for the tilelang path (JIT-compiles but the launched
//  kernel NEVER returns for num_heads in {32,64}) and deep_gemm's CUDA-only
//  fp8_paged_mqa_logits.
//
//  One wavefront (B lanes) per (batch, split_kv) block stages Q (H*D fp32)
//  and the per-head gate (H fp32) once, then -- per page -- one K tile
//  (B*D fp8->fp32) and the B per-token scales (fp32, packed in the trailing
//  B*4 bytes of each KV block). Total shared = (H*D + H + B*D + B) * 4 =
//  49,536 B at the GLM-5.3 config (H=32, D=128, B=64) -- UNDER the 64 KB
//  non-optin LDS cap, so NO hipFuncSetAttribute opt-in (unlike the MHC 256
//  KB bug). Each lane owns ONE KV token (j = lane), reuses the staged K
//  across all H heads, and writes out[b, i*B+lane] only when
//  t = i*B+lane < seq_len[b] (the caller ZEROES the output first). The
//  grid's split_kv slices [0, ceildiv(seq_len, B)) across the split blocks
//  and is perf-only (the grouped logit is grouping-independent, mirroring
//  the forward's block_I/inner_iter).
//
//  This is the simple, correct baseline (one lane per key, sequential H-sum,
//  K staged once per page and reused across all H heads) -- the topk's
//  counterpart to dsa_sparse_fwd's "one query row per wavefront, one key at
//  a time". A tiled-key / MFMA-fp8 prefetch is a follow-on optimisation,
//  not required for correctness.
// ---------------------------------------------------------------------------
__global__ void dsa_topk_logits_kernel(
    const uint8_t* __restrict__ q_fp8,
    const uint8_t* __restrict__ kvcache_u8,
    const float* __restrict__ weight,
    const int32_t* __restrict__ seq_lens,
    const int32_t* __restrict__ page_table,
    float* __restrict__ out,
    int H, int D, int B, int max_table_len, int max_seq_len, int split_kv) {
  const int b = blockIdx.x;
  const int pid_split = blockIdx.y;
  const int lane = threadIdx.x;                // 0..B-1 -> KV token j

  const int seq_len = seq_lens[b];
  const int np_total = (seq_len + B - 1) / B;  // pages with content
  const int stride = (np_total + split_kv - 1) / split_kv;
  const int i_start = pid_split * stride;
  const int rem = np_total - i_start;
  const int n_iters = (rem <= 0) ? 0 : (stride < rem ? stride : rem);
  if (n_iters <= 0) return;

  extern __shared__ float smem[];
  float* sQ = smem;                            // H * D
  float* sGate = sQ + (size_t)H * D;           // H
  float* sK = sGate + H;                       // B * D (reloaded per page)
  float* sKscale = sK + (size_t)B * D;         // B

  // --- cooperative load Q (H*D fp8 -> fp32) + gate (H fp32) once per block ---
  const uint8_t* qp = q_fp8 + (size_t)b * H * D;
  for (int idx = lane; idx < H * D; idx += B) sQ[idx] = fp8e4m3fnuz_to_f32(qp[idx]);
  const float* gp = weight + (size_t)b * H;
  for (int h = lane; h < H; h += B) sGate[h] = gp[h];
  __syncthreads();

  for (int it = 0; it < n_iters; ++it) {
    const int i = i_start + it;
    const int32_t page = page_table[(size_t)b * max_table_len + i];
    const uint8_t* kbase = kvcache_u8 + (size_t)page * (B * (D + 4));
    // keys: B*D fp8 e4m3fnuz (bytes [0 : B*D]); scales: B fp32 (bytes
    // [B*D : B*(D+4)], 4-aligned). Cooperative load into shared.
    for (int idx = lane; idx < B * D; idx += B) sK[idx] = fp8e4m3fnuz_to_f32(kbase[idx]);
    for (int j = lane; j < B; j += B) sKscale[j] = reinterpret_cast<const float*>(kbase + B * D)[j];
    __syncthreads();

    // --- this lane owns KV token j = lane within the page ---
    const float* kj = sK + (size_t)lane * D;
    float acc = 0.0f;
    for (int h = 0; h < H; ++h) {
      const float* qh = sQ + (size_t)h * D;
      float dot = 0.0f;
      for (int d = 0; d < D; ++d) dot += kj[d] * qh[d];
      acc += fmaxf(dot, 0.0f) * sGate[h];
    }
    const int t = i * B + lane;
    if (t < seq_len) out[(size_t)b * max_seq_len + t] = sKscale[lane] * acc;

    __syncthreads();                           // before reloading sK next iter
  }
}

void dsa_topk_logits(int batch_size, int num_heads, int head_dim, int block,
                     int max_table_len, int max_seq_len, int split_kv,
                     const void* q_fp8, const void* kvcache_u8,
                     const void* weight, const void* seq_lens,
                     const void* page_table, void* out) {
  if (batch_size <= 0 || max_table_len <= 0) return;  // nothing to write
  const int shmem = (num_heads * head_dim + num_heads +
                     block * head_dim + block) * sizeof(float);
  // One wavefront (B=64 lanes), one KV token per lane. Grid splits the
  // pages across split_kv blocks per batch (perf only; grouping-independent,
  // mirrors the forward's block_I/inner_iter). Stream 0 matches dsa_sparse_fwd;
  // the caller synchronises (see vkernels_dsa.tilelang_fp8_paged_mqa_logits).
  dim3 grid(batch_size, split_kv, 1);
  dim3 blockdim(block);
  dsa_topk_logits_kernel<<<grid, blockdim, shmem, 0>>>(
      reinterpret_cast<const uint8_t*>(q_fp8),
      reinterpret_cast<const uint8_t*>(kvcache_u8),
      reinterpret_cast<const float*>(weight),
      reinterpret_cast<const int32_t*>(seq_lens),
      reinterpret_cast<const int32_t*>(page_table),
      reinterpret_cast<float*>(out),
      num_heads, head_dim, block, max_table_len, max_seq_len, split_kv);
}

}  // namespace vkernels::kernels::hip

#endif  // VKERNELS_HAS_HIP

