    bool ok = st.max_rel < OUT_THRESH;
    std::printf("  bs=%-2d H=%-2d D=%-3d B=%-2d mt=%-2d nb=%-2d split=%d  "
                "out[a=%.4f r=%.6f]  %s\n",
                c.bs, c.H, c.D, c.B, c.mt, c.nb, c.split_kv, st.max_abs,
                st.max_rel, ok ? "PASS" : "FAIL");
    if (!ok) ++fails;
    ++ci;
